"""Signed join coefficients c(x) for the semilattice generated by noncrossing 2/3 certificates.
A(n,k) = sum_x c(x) * S(|x|, k), x ranging over joins of certificate subsets.
"""
import sys
from functools import lru_cache
from math import comb

def gen(l, r):
    if l == r:
        return [()]
    out = []
    for j in range(l + 1, r):
        for A in gen(l + 1, j):
            for B in gen(j + 1, r):
                out.append(((l, j),) + A + B)
    for j in range(l + 1, r):
        for k in range(j + 1, r):
            for A in gen(l + 1, j):
                for B in gen(j + 1, k):
                    for C in gen(k + 1, r):
                        out.append(((l, j, k),) + A + B + C)
    return out

def rgs_of_blocks(n, blocks):
    lab = list(range(n))
    for b in blocks:
        for p in b[1:]:
            lab[p] = b[0]
    return canon(lab)

def canon(lab):
    m, out, nxt = {}, [], 0
    for v in lab:
        if v not in m:
            m[v] = nxt; nxt += 1
        out.append(m[v])
    return tuple(out)

def join(x, y):
    n = len(x)
    parent = list(range(n))
    def f(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]; a = parent[a]
        return a
    for z in (x, y):
        first = {}
        for i, v in enumerate(z):
            if v in first:
                a, b = f(first[v]), f(i)
                if a != b: parent[b] = a
            else:
                first[v] = i
    return canon([f(i) for i in range(n)])

def stirling2(n, k):
    return sum((-1) ** (k - j) * comb(k, j) * j ** n for j in range(k + 1)) // _fact(k) if k else (1 if n == 0 else 0)

def _fact(k):
    r = 1
    for i in range(2, k + 1): r *= i
    return r

def run(n):
    certs = sorted({rgs_of_blocks(n, c) for c in gen(0, n)})
    coef = {}
    for g in certs:
        new = dict(coef)
        for x, c in coef.items():
            y = join(x, g)
            new[y] = new.get(y, 0) - c
        new[g] = new.get(g, 0) + 1
        coef = {x: c for x, c in new.items() if c != 0}
    return certs, coef

if __name__ == "__main__":
    n = int(sys.argv[1])
    certs, coef = run(n)
    nb = lambda x: max(x) + 1
    row = {}
    for x, c in coef.items():
        for k in range(1, n + 1):
            s = stirling2(nb(x), k)
            if s: row[k] = row.get(k, 0) + c * s
    print("n", n, "certs", len(certs), "support", len(coef), "row", [row.get(k, 0) for k in range(1, n // 2 + 1)])
